with candidate (n, title, artist, image_url, content, image_license, image_credit, image_page) as (
    values
    (1, 'デルフト眺望', 'ヨハネス・フェルメール', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c5/Johannes_Vermeer_-_View_of_Delft_-_92_-_Mauritshuis.jpg/960px-Johannes_Vermeer_-_View_of_Delft_-_92_-_Mauritshuis.jpg', 'フェルメールが暮らした街デルフトを、水辺の向こうから一望した作品です。1660年から1661年頃の制作で、ハーグのマウリッツハイス美術館が所蔵しています。室内画が中心のフェルメールにとって、風景画は本作と『小路』の2点だけです。建物の配置や寸法、水面に映る姿は現実から調整されています。19世紀にフェルメールが再評価されるきっかけとなり、ゴッホらが称賛し、作家プルーストも自作の重要な場面でこの絵を用いました。', 'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Johannes_Vermeer_-_View_of_Delft_-_92_-_Mauritshuis.jpg')
), fresh as (
    select c.*, row_number() over (order by c.n) as k
    from candidate c
    where not exists (select 1 from public.daily_columns d where d.title = c.title)
), free_day as (
    select day::date as display_date, row_number() over (order by day) as k
    from generate_series(
        (now() at time zone 'Asia/Tokyo')::date,
        (now() at time zone 'Asia/Tokyo')::date + 1
            + (select count(*)::int from public.daily_columns
               where display_date >= (now() at time zone 'Asia/Tokyo')::date),
        interval '1 day') as day
    where not exists (select 1 from public.daily_columns d where d.display_date = day::date)
)
insert into public.daily_columns (title, artist, image_url, content, image_license, image_credit, image_page, display_date)
select f.title, f.artist, f.image_url, f.content, f.image_license, f.image_credit, f.image_page, d.display_date
from fresh f join free_day d using (k)
on conflict (display_date) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('ヴェネチア・ビエンナーレ観客賞にニック・ケイヴ', '第61回ヴェネチア・ビエンナーレの観客投票による賞で、ニック・ケイヴとインド館が受賞した。', '第61回ヴェネチア・ビエンナーレ国際美術展は11月25日、観客投票による「ヴィジターズ・ライオン賞」の結果を発表した。最優秀アーティスト賞はアメリカのニック・ケイヴ、最優秀国別参加賞はインド館が受賞した。コヨ・クオがアーティスティック・ディレクターを務め「In Minor Keys」をテーマとした今回は、5月9日〜11月22日の会期中、プレビューを含め71万4015人が来場し、国別参加は過去最多の100か国にのぼった。同賞は国際審査員団の辞任を受けて設けられたもので、参加アーティストらから抗議が相次ぎ、日本館も閉幕を前に選考対象からの辞退を表明していた。', '', '作品・作家', 'https://bijutsutecho.com/magazine/news/headline/33384',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('第2回ブハラ・ビエンナーレ、テーマ発表', '2027年9月開幕の第2回ブハラ・ビエンナーレのテーマ「The Long Welcome」と参加作家が発表された。', 'ウズベキスタン芸術文化開発財団（ACDF）は、2027年に開催する第2回ブハラ・ビエンナーレのテーマと第1弾参加アーティストを発表した。会期は2027年9月3日〜11月21日、テーマは「The Long Welcome」。2025年に初開催された同ビエンナーレは180万人以上の来場者を集めた。今回は修復された歴史的建造物や公共空間を会場に開催エリアを広げ、委嘱作品はすべてウズベキスタン国内で制作される。アニッシュ・カプーアやウーゴ・ロンディノーネら13組が参加し、アーティスティック・ディレクターは建築設計事務所WHYの創設者クラパット・ヤントラサストが務める。庭園や噴水、ベンチなど、閉幕後も市民の生活に残る作品もつくられる予定だ。', '', '展覧会', 'https://bijutsutecho.com/magazine/news/headline/33380',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('地獄太夫図', 'Hell Courtesan', '河鍋暁斎', 'Kawanabe Kyōsai',
        null,
        (select slug from public.art_movements where slug = 'ukiyo-e'),
        'クリーブランド美術館', 'https://openaccess-cdn.clevelandart.org/1985.268/1985.268_web.jpg', '室町時代の遊女・地獄太夫を描いた掛軸です。伝説では、盗賊にさらわれた彼女は、今の苦しみは前世の罪の報いだと考え、地獄の図柄の衣をまとったといいます。暁斎はこの大画面の構図を何度も描き直しており、この作品では屏風の前に立つ太夫を弁財天に見立て、外衣には残りの七福神を描きました。その一人が閻魔大王に罪を報告する場面まで入っています。絹本に墨・色・金銀で描かれた1871〜89年頃の作です。歌川国芳に浮世絵を、狩野派に正統な画法を学んだ暁斎は、両者を合わせ、怖さと笑いが同居する明治の戯画の世界を切り開きました。',
        'CC0', 'The Cleveland Museum of Art', 'https://clevelandart.org/art/1985.268')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('ポントワーズの水門', 'The Lock at Pontoise', 'カミーユ・ピサロ', 'Camille Pissarro',
        1872,
        (select slug from public.art_movements where slug = 'impressionism'),
        'クリーブランド美術館', 'https://openaccess-cdn.clevelandart.org/1990.7/1990.7_web.jpg', 'パリの北西にある農村ポントワーズで、画家の家の近くにあった川の水門を描いた作品です。ピサロは1872年からポントワーズに住み、田園風景を描きました。勢いよく流れる水と曇り空は、純色をすばやく置いた途切れがちな筆づかいで表され、下描きなしにカンヴァスへ直接、一度の制作で描かれた可能性もあります。屋外で移ろう光と空気をとらえるこの描き方は、印象派の新しい技法そのものです。コローらの風景画から出発したピサロは、色を混ぜずに並べることで、明るい戸外の光を画面に呼び込みました。',
        'CC0', 'The Cleveland Museum of Art', 'https://clevelandart.org/art/1990.7')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('サン＝マメス、ロワン運河', 'Saint-Mammès, Loing Canal', 'アルフレッド・シスレー', 'Alfred Sisley',
        1885,
        (select slug from public.art_movements where slug = 'impressionism'),
        'クリーブランド美術館', 'https://openaccess-cdn.clevelandart.org/1961.262/1961.262_web.jpg', 'パリの南、セーヌ川とロワン川が運河で結ばれる小さな町サン＝マメスの眺めです。シスレーは1880年代にこの一帯を好んで何度も描きました。父の破産と死の後、困窮が続いていた彼にとって、家賃の安さも魅力だったと考えられています。純色と、やわらかくちらつく筆づかいが形を光のもやへと溶かし、明るい戸外の光の感覚を伝えます。仲間の多くが後に印象派の技法から離れていったのに対し、シスレーは生涯その画法を守り続け、最も典型的な印象派の画家とされます。',
        'CC0', 'The Cleveland Museum of Art', 'https://clevelandart.org/art/1961.262')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
