insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('夏', 'Summer', 'ピエール・ピュヴィス・ド・シャヴァンヌ', 'Pierre Puvis de Chavannes',
        1891,
        (select slug from public.art_movements where slug = 'symbolism'),
        'クリーブランド美術館', 'https://openaccess-cdn.clevelandart.org/1916.1056/1916.1056_web.jpg', 'パリ市庁舎のために描かれた同じ主題の壁画を、小さな画面で描いた作品です。壁画には対になる《冬》があります。当時の批評家は《夏》を「喜び、幸福、休息、そして生命の賛美に満ちている」と評しました。奥行きを抑えた平らな形と静かな色調で描かれた人物たちは、現実の再現というより夢のような理想の世界を思わせます。壁画の伝統を受け継ぎながら、自然らしさから離れた簡潔な様式を打ち出したピュヴィスは、スーラ、ゴーギャン、ピカソなど多くの近代の画家に影響を与えました。',
        'CC0', 'The Cleveland Museum of Art', 'https://clevelandart.org/art/1916.1056')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('カミーユ・ピサロ', 'Camille Pissarro', 'ピサロ',
        1830, 1903, 'west', array['impressionism']::text[],
        '全8回の印象派展にただ一人すべて参加した、フランスの印象派の画家。', 'カリブ海のセント・トーマス島（当時デンマーク領）で、フランス系ユダヤ人の家庭に生まれました。1855年に画家を志してパリに出て、コローに助言を求め、画塾アカデミー・シュイスでモネやセザンヌと知り合いました。

1869年からはルーヴシエンヌでモネ、シスレー、ルノワールらと戸外制作を行い、明るい色調の絵を描くようになります。1872年からはポントワーズに住んで田園風景を描き、1874年には仲間と第1回印象派展を開きました。全8回の印象派展すべてに参加したのはピサロだけです。1880年代後半にはスーラの点描に感化され、新印象主義を追求しました。

晩年は眼の病気もあり、パリやルーアンなどでホテルの部屋から都市の情景を描く連作を多く残しました。ゴッホやゴーギャン、スーラらにとって父親のような存在で、「印象派の父」とも呼ばれます。', 'https://ja.wikipedia.org/wiki/%E3%82%AB%E3%83%9F%E3%83%BC%E3%83%A6%E3%83%BB%E3%83%94%E3%82%B5%E3%83%AD')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('アルフレッド・シスレー', 'Alfred Sisley', 'シスレー',
        1839, 1899, 'west', array['impressionism']::text[],
        'パリ近郊の穏やかな風景を描き続けた、最も典型的な印象派の画家。', '裕福なイギリス人の両親のもと、パリで生まれました。18歳でロンドンに渡って商売を学びましたが、ターナーやコンスタブルの作品に触れて美術に惹かれ、パリに戻ってグレールのアトリエでモネ、ルノワールらと出会いました。

1870年の普仏戦争で家や財産を失い、翌年には父が破産すると、作品を売って暮らすしかなくなり、以後は生涯困窮が続きました。1880年代からはセーヌ川の支流ロワン川沿いに拠点を移し、川や運河、空を描きました。1893年からはモレ＝シュル＝ロワンの教会を連作で描いています。

残した900点近い油彩の大部分はパリ周辺の風景です。仲間の多くが後に印象派の技法から離れたのに対し、シスレーは生涯その画法を守り続けました。典型的な印象派の画家は誰かとマティスに問われたピサロが「シスレーだ」と答えた逸話が残っています。', 'https://ja.wikipedia.org/wiki/%E3%82%A2%E3%83%AB%E3%83%95%E3%83%AC%E3%83%83%E3%83%89%E3%83%BB%E3%82%B7%E3%82%B9%E3%83%AC%E3%83%BC')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('河鍋暁斎', 'Kawanabe Kyōsai', '暁斎',
        1831, 1889, 'japan', array['ukiyo-e', 'kano']::text[],
        '浮世絵と狩野派の両方を学び、幕末から明治にかけて戯画や風刺画で人気を集めた絵師。', '1831年、下総国古河（現在の茨城県古河市）に生まれ、幼くして江戸に出ました。1837年に浮世絵師の歌川国芳に入門し、その後、狩野派の前村洞和、さらに駿河台狩野家の洞白に学び、9年で修業を終えました。土佐派や琳派、四条派なども広く学んでいます。

1858年に狩野派を離れて「狂斎」と号し、戯画や風刺画で人気を得ました。1870年には書画会で新政府の役人を批判する戯画を描いて捕らえられ、翌年に放免されたのち「暁斎」と名乗ります。1881年の第2回内国勧業博覧会では《枯木寒鴉図》が妙技二等賞牌を受賞しました。

新富座のために4時間で描いた《新富座妖怪引幕》など、大胆な作品を残しています。英国人建築家ジョサイア・コンドルが弟子入りし、暁斎の技法を本でヨーロッパに紹介しました。1889年、胃癌のため亡くなりました。', 'https://ja.wikipedia.org/wiki/%E6%B2%B3%E9%8D%8B%E6%9A%81%E6%96%8E')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();
